#include <stdio.h>
#include <stdlib.h>

typedef struct Node {
    int value;
    struct Node *left;
    struct Node *right;
} Node;

// Читает дерево: n, затем n строк «значение левый правый». Возвращает корень или NULL.
static Node *read_tree(void) {
    int n;
    if (scanf("%d", &n) != 1 || n < 1 || n > 1000) {
        return NULL;
    }
    static Node *nodes[1000];
    static int left[1000], right[1000];
    for (int i = 0; i < n; i++) {
        nodes[i] = malloc(sizeof *nodes[i]);
        if (nodes[i] == NULL) {
            exit(1);
        }
        if (scanf("%d %d %d", &nodes[i]->value, &left[i], &right[i]) != 3) {
            exit(1);
        }
    }
    for (int i = 0; i < n; i++) {
        nodes[i]->left = left[i] >= 0 ? nodes[left[i]] : NULL;
        nodes[i]->right = right[i] >= 0 ? nodes[right[i]] : NULL;
    }
    return nodes[0];
}

static int size(const Node *t) {
    return t == NULL ? 0 : 1 + size(t->left) + size(t->right);
}

static int height(const Node *t) {
    if (t == NULL) {
        return -1;
    }
    int l = height(t->left), r = height(t->right);
    return 1 + (l > r ? l : r);
}

static int leaves(const Node *t) {
    if (t == NULL) {
        return 0;
    }
    if (t->left == NULL && t->right == NULL) {
        return 1;
    }
    return leaves(t->left) + leaves(t->right);
}

static void destroy(Node *t) {
    if (t == NULL) {
        return;
    }
    destroy(t->left);
    destroy(t->right);
    free(t);
}

int main(void) {
    Node *root = read_tree();
    if (root == NULL) {
        return 0;
    }
    printf("%d %d %d\n", size(root), height(root), leaves(root));
    destroy(root);
    return 0;
}

