        nodes[i]->left = left[i] >= 0 ? nodes[left[i]] : NULL;
        nodes[i]->right = right[i] >= 0 ? nodes[right[i]] : NULL;
    }
    return nodes[0];
}

static bool first;

static void put(int value) {
    printf(first ? "%d" : " %d", value);
    first = false;
}

static void preorder(const Node *t) {
    if (t == NULL) {
        return;
    }
    put(t->value);
    preorder(t->left);
    preorder(t->right);
}

static void inorder(const Node *t) {
    if (t == NULL) {
        return;
    }
    inorder(t->left);
    put(t->value);
    inorder(t->right);
}

static void postorder(const Node *t) {
    if (t == NULL) {
        return;
    }
    postorder(t->left);
    postorder(t->right);
    put(t->value);
}

static void destroy(Node *t) {
    if (t == NULL) {
        return;
    }
    destroy(t->left);
    destroy(t->right);
    free(t);
}

int main(void) {
    Node *root = read_tree();
    if (root == NULL) {
        return 0;
    }
    void (*orders[])(const Node *) = {preorder, inorder, postorder};
    for (int i = 0; i < 3; i++) {
        first = true;
        orders[i](root);
        printf("\n");
    }
    destroy(root);
    return 0;
}

