typedef struct Node {
    int value;
    struct Node *left, *right;
} Node;

static int f(const Node *t) {
    if (t == NULL) {
        return 0;
    }
    int l = f(t->left), r = f(t->right);
    return t->value + (l > r ? l : r);
}

int main(void) {
    Node d = {4, NULL, NULL}, e = {9, NULL, NULL};
    Node b = {2, &d, NULL}, c = {1, NULL, &e};
    Node a = {5, &b, &c};
    printf("%d\n", f(&a));
    return 0;
}
